namespace Qms.Domain.RiskManagement;
public sealed class RiskLookupDefinition{private RiskLookupDefinition(){}public Guid Id{get;private set;}public string Category{get;private set;}="";public string Code{get;private set;}="";public string Name{get;private set;}="";public int SortOrder{get;private set;}public bool IsActive{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public static RiskLookupDefinition Create(string c,string code,string name,int order,DateTimeOffset now){Validate(c,code,name,order);return new(){Id=Guid.CreateVersion7(),Category=c.Trim(),Code=code.Trim(),Name=name.Trim(),SortOrder=order,IsActive=true,CreatedAtUtc=now,UpdatedAtUtc=now};}public void Update(string name,int order,bool active,DateTimeOffset now){Validate(Category,Code,name,order);Name=name.Trim();SortOrder=order;IsActive=active;UpdatedAtUtc=now;}private static void Validate(string c,string code,string name,int order){if(c.Trim() is not("Category" or "Methodology" or "MatrixVersion")||string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name)||order<0)throw new ArgumentException("M.11 lookup tanımı geçersizdir.");}}
